"""Server-side connection factory implementations."""

import logging
import typing

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.aio.interface import IAcceptor, IReactor

from . import _globals, exc
from .connection import TransportConnection
from .interface import ITransportAcceptor, ITransportConnection

__all__ = export = _utils.ExportList()

logger = logging.getLogger(_globals.LOGGER_NAME)


@export
class TransportAcceptor(ITransportAcceptor):
    """Transport layer acceptor that accepts low-level stream connections and
    wraps with :class:`TransportConnection` instances.

    :param reactor:
        Reactor to be used.

    :param target:
        Target stream acceptor.
    """

    def __init__(self, reactor: IReactor, target: IAcceptor):

        @_utils.log_exceptions(logger)
        async def accept_loop():
            while not target.is_closed():
                stream = await target.accept()
                connection = TransportConnection(reactor, stream)
                self._forwarder.dispatch(connection)

        self._closed = False
        self._forwarder = ForwardingTransportAcceptor()
        self._accept_loop_task = reactor.run(accept_loop())

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            await self._accept_loop_task.cancel()

    async def accept(self) -> ITransportConnection:
        connection = await self._forwarder.accept()
        logger.debug('[%s] Connection accepted (%s)', _utils.get_obj_addr(self), _utils.get_obj_addr(connection))
        return connection


@export
class ForwardingTransportAcceptor(ITransportAcceptor):
    """Transport acceptor that awaits on a queue for incoming instances of
    :class:`ITransportConnection` class.

    This class can be used for easier testing of upper layers instead of
    mocking :class:`ITransportAcceptor` interface directly.
    """

    def __init__(self):
        self._queue: asyncio.Queue[typing.Optional[ITransportConnection]] = asyncio.Queue()
        self._closed = False

    def dispatch(self, connection: ITransportConnection):
        self._queue.put_nowait(connection)

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            self._queue.put_nowait(None)

    async def accept(self) -> ITransportConnection:
        if self._closed:
            raise exc.AcceptorClosedError()
        maybe_connection = await self._queue.get()
        if maybe_connection is None:
            raise exc.AcceptorClosedError()
        return maybe_connection
